import os
import re
import ast

def analyze():
    py_files = []
    for root, dirs, files in os.walk('.'):
        for file in files:
            if file.endswith('.py') and file != 'inspect_auth.py':
                py_files.append(os.path.join(root, file))

    for filepath in sorted(py_files):
        with open(filepath, 'r') as f:
            content = f.read()
        if 'legacy_auth' in content and filepath != './app/auth.py':
            print(f"File: {filepath}")
            try:
                tree = ast.parse(content, filename=filepath)
            except SyntaxError:
                print(f"  SyntaxError parsing {filepath}")
                continue

            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    func_str = ast.get_source_segment(content, node)
                    if func_str and 'legacy_auth' in func_str:
                        keywords = ['create_', 'update_', 'delete_', 'save_', 'write_', 'POST', 'PUT', 'PATCH']
                        matches = []
                        for kw in keywords:
                            if kw in func_str:
                                matches.append(kw)
                        print(f"  Function: {node.name} (line {node.lineno})")
                        print(f"    Matches: {matches}")
                        print(f"    Code snippet:")
                        for l in func_str.splitlines():
                            print(f"      {l}")

if __name__ == '__main__':
    analyze()

