import os
import re
import ast

def analyze():
    py_files = []
    for root, dirs, files in os.walk('.'):
        for file in files:
            if file.endswith('.py') and file != 'inspect_auth.py':
                py_files.append(os.path.join(root, file))

    for filepath in sorted(py_files):
        with open(filepath, 'r') as f:
            content = f.read()
        if 'legacy_auth' in content and filepath != './app/auth.py':
            try:
                tree = ast.parse(content, filename=filepath)
            except SyntaxError:
                continue

            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    func_str = ast.get_source_segment(content, node)
                    if func_str and 'legacy_auth' in func_str:
                        # Search for broad keywords
                        broad_kws = ['create', 'update', 'delete', 'save', 'write', 'post', 'put', 'patch']
                        found = []
                        for kw in broad_kws:
                            if re.search(r'\b' + kw + r'\b', func_str, re.IGNORECASE) or kw in func_str.lower():
                                found.append(kw)
                        if found:
                            print(f"File: {filepath}, Function: {node.name}")
                            print(f"  Broad matches: {found}")
                            print(f"  Code snippet:")
                            for l in func_str.splitlines():
                                print(f"    {l}")

if __name__ == '__main__':
    analyze()

