        if filepath == './app/auth.py':
            continue

        with open(filepath, 'r') as f:
            content = f.read()

        if 'legacy_auth' not in content and 'new_auth' not in content:
            continue

        try:
            tree = ast.parse(content, filename=filepath)
        except SyntaxError:
