            # Perform legacy_auth / new_auth replacement within this function body
            # Matches legacy_auth(user_id) or new_auth(user_id, scope="write") etc.
            new_func_body = re.sub(
                r'\b(?:legacy_auth|new_auth)\(([^,)]+)(?:,\s*scope\s*=\s*["\']\w+["\'])?\)',
                rf'new_auth(\1, scope="{scope}")',
                func_body
            )

            modified_content = modified_content.replace(func_body, new_func_body)

